async function pairAdminInFirstRun(){try{const session=await api('/api/onboarding/pair-admin/session',{method:'POST',body:'{}'});await api('/api/onboarding/pair-admin/complete',{method:'POST',body:JSON.stringify({token:session.token,code:session.code})});await refresh(false);renderFirstRun();toast('Administrator sicher lokal verbunden')}catch(error){toast(`${error.code||'FEHLER'}: ${error.message}`)}}
