function renderOverview(state){const online=state.devices.filter(device=>device.online).length,offline=state.devices.length-online,active=(state.automations||[]).filter(item=>item.enabled).length,definitions={online:{value:online,label:'Geräte bereit',open:'devices'},offline:{value:offline,label:offline?'Braucht Aufmerksamkeit':'Keine Störung',open:'devices',attention:Boolean(offline)},automations:{value:active,label:'Automationen aktiv',open:'automations'},backup:{value:'Lokal',label:'Cloudfrei gesichert',open:'backup'}},layout=state.dashboard||{widgets:Object.keys(definitions).map(id=>({id,visible:true,size:'normal'})),quickAction:'devices'};document.querySelector('#overviewStats').innerHTML=layout.widgets.filter(widget=>widget.visible).map(widget=>{const item=definitions[widget.id];return `<button class="stat-card ${item.attention?'attention':''} ${widget.size==='wide'?'wide':''}" data-open="${item.open}"><span class="stat-number">${item.value}</span><span>${item.label}</span></button>`}).join('');const quick=document.querySelector('.round-action');quick.setAttribute('aria-label',`Schnellzugriff: ${{devices:'Geräte',automations:'Automationen',backup:'Backup'}[layout.quickAction]}`);document.querySelectorAll('.stat-card[data-open]').forEach(card=>card.addEventListener('click',()=>showView(card.dataset.open)))}

