const dashboardEditor=document.createElement('dialog');dashboardEditor.className='dashboard-editor';dashboardEditor.innerHTML='<div class="wizard-head"><div><p class="eyebrow">DASHBOARD</p><h2>Home anpassen</h2></div><button class="icon-button" data-editor-close aria-label="Schließen">×</button></div><p class="muted">Reihenfolge, Sichtbarkeit, Größe und Schnellzugriff – Änderungen erscheinen sofort als Vorschau.</p><div id="dashboardEditorRows"></div><label class="dashboard-quick">Schnellzugriff<select id="dashboardQuick"><option value="devices">Geräte</option><option value="automations">Automationen</option><option value="backup">Backup</option></select></label><div class="wizard-actions"><button id="dashboardReset" class="secondary">Standard</button><button id="dashboardCancel" class="secondary">Abbrechen</button><button id="dashboardSave" class="primary">Speichern</button></div>';document.body.append(dashboardEditor);
