const editDashboardButton=document.createElement('button');editDashboardButton.className='dashboard-edit-action';editDashboardButton.setAttribute('aria-label','Dashboard bearbeiten');editDashboardButton.textContent='✎';document.querySelector('.home-heading')?.append(editDashboardButton);editDashboardButton.addEventListener('click',()=>{dashboardDraft=structuredClone(latestState.dashboard);renderDashboardEditor();dashboardEditor.showModal()});document.querySelector('[data-editor-close]').addEventListener('click',()=>{dashboardEditor.close();renderOverview(latestState)});document.querySelector('#dashboardCancel').addEventListener('click',()=>{dashboardEditor.close();renderOverview(latestState)});document.querySelector('#dashboardQuick').addEventListener('change',event=>{dashboardDraft.quickAction=event.target.value;previewDashboard()});document.querySelector('#dashboardSave').addEventListener('click',async()=>{try{await api('/api/dashboard',{method:'PATCH',body:JSON.stringify(dashboardDraft)});dashboardEditor.close();await refresh(false);toast('Dashboard lokal gespeichert')}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}});document.querySelector('#dashboardReset').addEventListener('click',async()=>{try{await api('/api/dashboard/reset',{method:'POST',body:'{}'});dashboardEditor.close();await refresh(false);toast('Dashboard auf Standard zurückgesetzt')}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}})
const wizardTitles=['Integration wählen','Gerät erkennen','Raum und Name','Prüfen und hinzufügen'];
function renderWizard(){const title=wizardStep===1?'Gerät erkennen':wizardTitles[wizardStep];document.querySelector('#wizardTitle').textContent=title;document.querySelectorAll('.wizard-progress span').forEach((item,index)=>item.classList.toggle('active',index<=wizardStep));document.querySelector('#wizardBack').disabled=wizardStep===0;document.querySelector('#wizardNext').textContent=wizardStep===3?'Gerät testen & hinzufügen':'Weiter';const content=document.querySelector('#wizardContent');if(wizardStep===0)content.innerHTML=`<div class="choice-grid">${wizardIntegrations.map(item=>`<label class="choice-card ${item.available?'':'disabled'}"><input type="radio" name="wizardIntegration" value="${esc(item.id)}" ${wizardData.integration===item.id?'checked':''} ${item.available?'':'disabled'}><strong>${esc(item.name)}</strong><span>${esc(item.description)}</span>${item.recommended?'<em>Empfohlen</em>':''}</label>`).join('')}</div>`;if(wizardStep===1){content.innerHTML=`<div class="discovery-head"><p class="muted">${wizardCandidates.length?'Gefundene Geräte mit Hersteller und stabiler Identität.':'Keine Geräte gefunden.'}</p><button id="retryDiscovery" class="secondary">Erneut suchen</button></div><div class="choice-grid profiles">${wizardCandidates.map(item=>`<label class="choice-card ${item.alreadyAdded?'disabled':''}"><input type="radio" name="wizardCandidate" value="${esc(item.id)}" ${wizardData.candidateId===item.id?'checked':''} ${item.alreadyAdded?'disabled':''}><strong>${esc(item.suggestedName)}</strong><span>${esc(item.manufacturer)} · ${esc(item.model)}</span><em>${item.alreadyAdded?'Bereits hinzugefügt':'Keine Kopplung nötig'}</em></label>`).join('')}</div>`;document.querySelector('#retryDiscovery').addEventListener('click',discoverWizardDevices)}if(wizardStep===2)content.innerHTML=`<div class="wizard-form"><label>Name<input id="wizardName" maxlength="60" value="${esc(wizardData.name)}" placeholder="z. B. Stehlampe"></label><label>Raum<select id="wizardRoom"><option value="">Ohne Raum</option>${latestState.rooms.map(room=>`<option value="${esc(room.id)}" ${wizardData.roomId===room.id?'selected':''}>${esc(room.name)}</option>`).join('')}</select></label></div>`;if(wizardStep===3){const candidate=wizardCandidates.find(item=>item.id===wizardData.candidateId);content.innerHTML=`<div class="wizard-review"><span class="device-icon">✓</span><div><strong>${esc(wizardData.name||'Unbenanntes Gerät')}</strong><p class="muted">${esc(candidate?.manufacturer||'SystemONE')} · ${esc(candidate?.model||profileLabel(wizardData.profile))} · ${esc(latestState.rooms.find(room=>room.id===wizardData.roomId)?.name||'Ohne Raum')}</p></div></div><p class="muted">Identität, Erreichbarkeit und Funktionen werden lokal getestet. Bei einem Fehler bleibt dieser Schritt zum Wiederholen geöffnet.</p>`}}
const renderWizardBase=renderWizard;renderWizard=function(){renderWizardBase();if(wizardStep===0){document.querySelector('#wizardContent').insertAdjacentHTML('beforeend',`<label class="experimental-consent"><input id="experimentalAccepted" type="checkbox" ${wizardData.experimentalAccepted?'checked':''}><span><strong>Experimentelle Integration bewusst aktivieren</strong><small>Nur lokal, ohne Cloudkonto. Simulation und Hue-Pilot besitzen noch keine vollständige Hardwaregarantie.</small></span></label>`);document.querySelector('#experimentalAccepted').addEventListener('change',event=>{wizardData.experimentalAccepted=event.target.checked})}};
async function discoverWizardDevices(){try{const result=await api(`/api/device-onboarding/discover?integration=${encodeURIComponent(wizardData.integration)}`);wizardCandidates=result.candidates;renderWizard();toast(`${wizardCandidates.filter(item=>!item.alreadyAdded).length} verfügbare Geräte gefunden`)}catch(e){wizardCandidates=[];renderWizard();toast(`${e.code||'DISCOVERY_FAILED'}: ${e.message}`)}}
function captureWizard(){const integration=document.querySelector('input[name="wizardIntegration"]:checked'),candidateInput=document.querySelector('input[name="wizardCandidate"]:checked');if(integration)wizardData.integration=integration.value;if(wizardStep===0&&!document.querySelector('#experimentalAccepted')?.checked)throw new Error('Bitte bestätige die bewusste Nutzung der experimentellen Integration.');if(wizardStep===1){if(!candidateInput)throw new Error('Bitte wähle ein gefundenes Gerät.');const candidate=wizardCandidates.find(item=>item.id===candidateInput.value);wizardData.candidateId=candidate.id;wizardData.profile=candidate.profile;if(!wizardData.name)wizardData.name=candidate.suggestedName}if(wizardStep===2){wizardData.name=document.querySelector('#wizardName').value.trim();wizardData.roomId=document.querySelector('#wizardRoom').value;if(!wizardData.name)throw new Error('Bitte gib dem Gerät einen Namen.')}}
function controlHtml(d){const c=d.capabilities||{},name=esc(d.name);if(d.profile==='light')return `<div class="control-stack"><label>Helligkeit <input aria-label="Helligkeit von ${name}" class="brightness" type="range" min="0" max="100" value="${c.brightness??50}"></label>${c.colorTemperature?`<label>Weißton <input aria-label="Weißton von ${name}" class="color-temperature" type="range" min="153" max="500" value="${c.colorTemperature}"></label>`:''}${c.color?`<label>Farbe <input aria-label="Farbe von ${name}" class="color" type="color" value="${c.color}"></label>`:''}</div><button aria-label="${name} ${c.power?'ausschalten':'einschalten'}" class="switch ${c.power?'on':''}"></button>`;if(d.profile==='switch')return `<div class="metric"><strong>${esc(c.powerConsumption??0)} W</strong><span>${esc(c.energy??0)} kWh</span></div><button aria-label="${name} ${c.power?'ausschalten':'einschalten'}" class="switch ${c.power?'on':''}"></button>`;if(d.profile==='sensor')return `<div class="metric"><strong>${esc(c.value)} ${esc(c.unit)}</strong><span>${esc(c.sensorType||'Sensor')}</span></div>`;if(d.profile==='thermostat')return `<div class="metric"><strong>${esc(c.temperature)}°C</strong><span>${c.heating?'Heizt':'Bereit'} · ${esc(c.mode||'auto')}</span></div><input aria-label="Zieltemperatur von ${name}" class="target" type="number" min="5" max="35" step="0.5" value="${c.targetTemperature}">`;if(d.profile==='blind')return `<div class="blind-controls"><button class="blind-action secondary" data-action="open">Öffnen</button><button class="blind-action secondary" data-action="stop">Stop</button><button class="blind-action secondary" data-action="close">Schließen</button><input aria-label="Position von ${name}" class="position" type="range" min="0" max="100" value="${c.position??50}"></div>`;return ''}
function profileLabel(profile){return({light:'Licht',switch:'Schalter',sensor:'Sensor',thermostat:'Thermostat',blind:'Rollladen'})[profile]||profile}
function decorateDeviceCards(state){for(const device of state.devices){const card=document.querySelector(`.device[data-device-id="${CSS.escape(device.id)}"]`);if(!card)continue;const battery=device.capabilities?.battery;if(Number.isFinite(battery)){const badge=document.createElement('span');badge.className=`battery-badge ${battery<=20?'low':''}`;badge.textContent=`Batterie ${battery}%`;card.querySelector('.device-heading')?.append(badge)}const details=document.createElement('details');details.className='device-information';const summary=document.createElement('summary');summary.textContent='Geräteinformationen';const copy=document.createElement('p');copy.textContent=`Modell ${device.model} · Firmware ${device.information?.firmwareVersion||'unbekannt'} · Seriennummer ${device.information?.serialNumber||'nicht verfügbar'}`;details.append(summary,copy);card.querySelector('.device-main')?.append(details)}}
function decorateCompatibilityCards(state){const copy={certified:['SystemONE Certified','Vollständig getestet und regulär unterstützt.'],compatible:['SystemONE Compatible','Kernfunktionen getestet; modellbezogene Einschränkungen beachten.'],experimental:['Experimentell / Beta','Bewusst aktiviert; keine vollständige Hardwaregarantie.'],unsupported:['Nicht unterstützt','Nicht für den normalen Einrichtungsablauf freigegeben.']};for(const device of state.devices){const card=document.querySelector(`.device[data-device-id="${CSS.escape(device.id)}"]`),info=copy[device.compatibility]||copy.unsupported;if(!card||card.querySelector('.compatibility-info'))continue;card.querySelector('.device-main')?.insertAdjacentHTML('beforeend',`<details class="compatibility-info"><summary>${esc(info[0])}</summary><p class="muted">${esc(info[1])} ${device.integration==='hue'?'Lokale Bridge, keine Hue-Cloud.':'Vollständig lokal, kein Cloudkonto.'}</p></details>`)}}
function bindExtendedControls(){document.querySelectorAll('.device').forEach(card=>{const id=card.dataset.deviceId,patch=async capabilities=>{try{await api(`/api/devices/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({capabilities})});await refresh(false)}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}};card.querySelector('.color-temperature')?.addEventListener('change',e=>patch({colorTemperature:Number(e.target.value)}));card.querySelector('.color')?.addEventListener('change',e=>patch({color:e.target.value}));card.querySelectorAll('.blind-action').forEach(button=>button.addEventListener('click',async()=>{try{await api(`/api/devices/${encodeURIComponent(id)}/actions/${button.dataset.action}`,{method:'POST',body:'{}'});await refresh(false);toast(`Rollladen: ${button.textContent}`)}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}}))})}
function renderRooms(state){const unassigned=state.devices.filter(d=>!state.rooms.some(r=>r.id===d.roomId));const rooms=[...state.rooms,...(unassigned.length?[{id:'__unassigned',name:'Nicht zugeordnet'}]:[])];roomsEl.innerHTML=rooms.map(room=>{const devices=room.id==='__unassigned'?unassigned:state.devices.filter(d=>d.roomId===room.id);const html=devices.length?devices.map(d=>`<div class="device ${d.online?'':'offline'}" data-device-id="${esc(d.id)}"><div class="device-main"><div class="device-heading"><span class="device-icon">${d.profile==='light'?'●':d.profile==='sensor'?'◇':d.profile==='thermostat'?'°':'◆'}</span><div class="device-name">${esc(d.name)}</div><span class="badge ${d.online?'success':'error'}">${d.online?'Bereit':'Nicht erreichbar'}</span></div><div class="device-meta">${esc(profileLabel(d.profile))} · ${esc(d.manufacturer)} · ${d.compatibility==='certified'?'SystemONE Certified':esc(d.compatibility)}</div>${d.online?'':`<div class="device-alert"><strong>Gerät antwortet nicht</strong><span>${esc(d.diagnostics?.lastError||'Verbindung wird automatisch erneut versucht.')}</span><button class="retry-device secondary">Erneut versuchen</button></div>`}<div class="device-edit"><input class="name-input" value="${esc(d.name)}"><select class="room-select"><option value="">Raum wählen</option>${state.rooms.map(r=>`<option value="${esc(r.id)}" ${r.id===d.roomId?'selected':''}>${esc(r.name)}</option>`).join('')}</select><button class="save-device secondary">Speichern</button></div></div><div class="controls">${d.online?controlHtml(d):''}</div></div>`).join(''):'<div class="empty-state"><span>＋</span><p>Noch keine Geräte in diesem Raum.</p></div>';return `<article class="room-card"><div class="room-top"><div><p class="eyebrow">RAUM</p><h3>${esc(room.name)}</h3></div><span class="badge">${devices.length} ${devices.length===1?'Gerät':'Geräte'}</span></div><div class="device-list">${html}</div></article>`}).join('');bindDevices()}
function bindDevices(){document.querySelectorAll('.device').forEach(el=>{const id=el.dataset.deviceId;const send=async patch=>{try{await api(`/api/devices/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify(patch)});await refresh(false);toast('Änderung gespeichert')}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}};el.querySelector('.switch')?.addEventListener('click',e=>send({capabilities:{power:!e.currentTarget.classList.contains('on')}}));el.querySelector('.brightness')?.addEventListener('change',e=>send({capabilities:{brightness:Number(e.target.value)}}));el.querySelector('.target')?.addEventListener('change',e=>send({capabilities:{targetTemperature:Number(e.target.value)}}));el.querySelector('.position')?.addEventListener('change',e=>send({capabilities:{position:Number(e.target.value)}}));el.querySelector('.save-device')?.addEventListener('click',()=>send({name:el.querySelector('.name-input').value.trim(),roomId:el.querySelector('.room-select').value}));el.querySelector('.retry-device')?.addEventListener('click',async()=>{try{await api('/api/integrations/hue/reconnect',{method:'POST',body:'{}'});await refresh(false);toast('Verbindung wird erneut geprüft')}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}})})}
function renderHeader(s){const h=s.integrations.hue,rc=h.reconnect||{};bridgeStatusEl.textContent=h.mode==='simulation'?`Hue Simulation · ${rc.state||'sicher'}`:h.paired?(h.syncError?`Hue · ${rc.state||'Syncfehler'}`:'Hue verbunden'):h.discovered?'Hue Bridge gefunden':'Keine Bridge gefunden';document.querySelector('#pairHue').textContent=h.mode==='simulation'?(h.paired?'Simulation verbunden':'Simulation starten'):(h.paired?'Hue verbunden':h.discovered?'Link-Taste drücken & koppeln':'Hue suchen');document.querySelector('#pairHue').disabled=h.paired;document.querySelector('#pairAdmin').textContent=s.onboarding.adminPaired?(hasLocalSession?'Admin gekoppelt':'Session erneuern'):'Admin-Pairing starten';document.querySelector('#pairAdmin').disabled=s.onboarding.adminPaired&&hasLocalSession}
async function renderSetup(){try{const s=await api('/api/setup');document.querySelector('#setupSteps').innerHTML=s.steps.map(step=>`<div class="setup-step ${step.done?'done':''}"><span>${step.done?'✓':'○'}</span><span>${esc(step.label)}</span></div>`).join('');document.querySelector('#setupHeadline').textContent=s.completed?'Einrichtung theoretisch abgeschlossen':'SystemONE Schritt für Schritt';document.querySelector('#setupHint').textContent=s.completed?'Alle aktuellen MVP-Prüfschritte sind erfüllt. Ein echter Hue-Hardwaretest bleibt bewusst separat.':`Nächster Schritt: ${s.steps.find(x=>!x.done)?.label||'fertig'}`;}catch(e){}}
async function renderDiagnostics(){try{const d=await api('/api/diagnostics'),r=d.reconnect||{};document.querySelector('#diagnosticStatus').textContent=`${d.health.status.toUpperCase()} · ${d.hue.mode}`;document.querySelector('#reconnectStatus').textContent=`Reconnect: ${r.state||'idle'}${r.attempt?` · Versuch ${r.attempt}`:''}${r.nextRetryAt?` · nächster Versuch ${new Date(r.nextRetryAt).toLocaleTimeString()}`:''}`;document.querySelector('#diagnosticList').innerHTML=[...d.health.recentErrors,...d.health.recentWarnings].slice(0,5).map(e=>`<li><strong>${esc(e.code)}</strong> – ${esc(e.message)}</li>`).join('')||'<li>Keine Fehler protokolliert.</li>'}catch(e){}}
function automationTriggerLabel(automation,state){if(automation.trigger.type==='sun'){const event=automation.trigger.event==='sunrise'?'Sonnenaufgang':'Sonnenuntergang',offset=automation.trigger.offsetMinutes,offsetCopy=offset?` ${offset>0?'+':''}${offset} Min.`:'';return `${event}${offsetCopy} · ${state.home?.location?'lokal berechnet':'wartet auf lokalen Standort'}`}if(automation.trigger.type==='time')return `Täglich ${automation.trigger.at}`;return 'Geräteereignis'}
function renderAutomations(state){const list=state.automations||[];document.querySelector('#automationList').innerHTML=list.length?list.map(a=>`<article class="automation-item"><div><strong>${esc(a.name)}</strong><p class="muted">${esc(automationTriggerLabel(a,state))} · ${a.enabled?'Aktiv':'Pausiert'} · ${a.conditions.length} Bedingungen · ${a.actions.length} Aktionen${a.lastRun?` · zuletzt ${new Date(a.lastRun).toLocaleString()}`:''}${a.lastError?` · ${esc(a.lastError.code)}`:''}</p></div><div class="automation-actions"><button class="secondary toggle-automation" data-id="${esc(a.id)}" data-enabled="${a.enabled}">${a.enabled?'Pausieren':'Aktivieren'}</button><button class="secondary delete-automation" data-id="${esc(a.id)}">Löschen</button></div></article>`).join(''):'<p class="muted">Noch keine Automation angelegt.</p>';document.querySelectorAll('.toggle-automation').forEach(button=>button.addEventListener('click',async()=>{await api(`/api/automations/${encodeURIComponent(button.dataset.id)}`,{method:'PATCH',body:JSON.stringify({enabled:button.dataset.enabled!=='true'})});await refresh(false)}));document.querySelectorAll('.delete-automation').forEach(button=>button.addEventListener('click',async()=>{await api(`/api/automations/${encodeURIComponent(button.dataset.id)}`,{method:'DELETE'});await refresh(false)}))}
document.querySelector('#automationList').insertAdjacentHTML('afterend','<section class="automation-history"><div><p class="eyebrow">VERLAUF</p><h3>Letzte Ausführungen</h3><p id="schedulerTimezone" class="muted">Maximal 100 lokale Einträge; ältere werden automatisch rotiert.</p></div><div id="automationHistory"><p class="muted">Noch keine Ausführung.</p></div></section>');
async function renderAutomationHistory(){const [history,scheduler]=await Promise.all([api('/api/automations/history'),api('/api/automations/scheduler')]),root=document.querySelector('#automationHistory');document.querySelector('#schedulerTimezone').textContent=`Lokale Zeitzone: ${scheduler.timezone} · Neustart- und DST-Duplikatschutz aktiv · maximal 100 Einträge.`;root.innerHTML=history.length?history.map(item=>`<article class="history-item ${item.success?'success':'error'}"><div><strong>${item.success?'✓':'!'} ${esc(item.automationName)}</strong><p class="muted">${new Date(item.timestamp).toLocaleString()} · ${item.success?'Erfolgreich':esc(item.error?.code||'Fehlgeschlagen')} · ${item.completedActionCount}/${item.totalActions} Aktionen</p>${item.error?`<small>${esc(item.error.message)}</small>`:''}</div>${!item.success&&!item.retriedBy?`<button class="secondary retry-execution" data-id="${esc(item.id)}">Sicher wiederholen</button>`:item.retriedBy?'<span class="badge">Wiederholt</span>':''}</article>`).join(''):'<p class="muted">Noch keine Ausführung.</p>';document.querySelectorAll('.retry-execution').forEach(button=>button.addEventListener('click',async()=>{try{await api(`/api/automations/history/${encodeURIComponent(button.dataset.id)}/retry`,{method:'POST',body:'{}'});await refresh(false);toast('Nur die noch offenen Aktionen wurden wiederholt')}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}}))}
function populateAutomationDevices(state){const devices=state.devices||[],trigger=document.querySelector('#automationTrigger'),action=document.querySelector('#automationAction');const selectedTrigger=trigger.value,selectedAction=action.value;trigger.innerHTML=devices.map(d=>`<option value="${esc(d.id)}">Wenn: ${esc(d.name)} (${esc(d.profile)})</option>`).join('')||'<option value="">Zuerst Gerät anlegen</option>';action.innerHTML=devices.map(d=>`<option value="${esc(d.id)}">Dann: ${esc(d.name)} (${esc(d.profile)})</option>`).join('')||'<option value="">Zuerst Gerät anlegen</option>';if(devices.some(d=>d.id===selectedTrigger))trigger.value=selectedTrigger;if(devices.some(d=>d.id===selectedAction))action.value=selectedAction}
function populateAutomationExtras(state){const devices=state.devices||[],options=devices.map(d=>`<option value="${esc(d.id)}">${esc(d.name)} (${esc(d.profile)})</option>`).join('');for(const selector of ['#automationAction2','#automationConditionDevice']){const select=document.querySelector(selector),selected=select?.value;if(!select)continue;select.innerHTML=`<option value="">${selector.includes('Action2')?'Keine zweite Aktion':'Keine Bedingung'}</option>${options}`;if(devices.some(d=>d.id===selected))select.value=selected}}
function populateHome(state){if(document.activeElement?.closest?.('.home-settings'))return;document.querySelector('#homeName').value=state.home?.name||'';document.querySelector('#homeLatitude').value=state.home?.location?.latitude??'';document.querySelector('#homeLongitude').value=state.home?.location?.longitude??''}
async function refresh(sync=true){latestState=await api(`/api/state${sync?'?sync=1':''}`);hasLocalSession=false;if(latestState.onboarding?.adminPaired){try{await api('/api/session');hasLocalSession=true}catch{}}applyTheme(latestState.onboarding?.selectedTheme||'Clear');document.querySelector('#localeSelect').value=latestState.onboarding?.locale||'de';document.documentElement.lang=latestState.onboarding?.locale||'de';renderOverview(latestState);renderRooms(latestState);decorateDeviceCards(latestState);decorateCompatibilityCards(latestState);bindExtendedControls();renderHeader(latestState);renderAutomations(latestState);populateAutomationDevices(latestState);populateAutomationExtras(latestState);populateHome(latestState);await Promise.all([renderDiagnostics(),renderSetup(),renderAutomationHistory()])}
function scheduleLiveRefresh(){clearTimeout(liveRefreshTimer);liveRefreshTimer=setTimeout(()=>{if(!document.hidden)refresh(false).catch(()=>{})},120)}
function startFallbackPolling(){if(liveTimer)return;liveTimer=setInterval(()=>{if(!document.hidden)refresh(false).catch(()=>{})},15000)}
function startDeviceEvents(){if(!window.EventSource)return startFallbackPolling();liveSource=new EventSource('/api/events/devices');for(const type of ['device.added','device.updated','devices.resync'])liveSource.addEventListener(type,scheduleLiveRefresh);liveSource.onopen=()=>{clearInterval(liveTimer);liveTimer=null};liveSource.onerror=()=>startFallbackPolling()}
document.querySelector('#pairAdmin').addEventListener('click',async()=>{try{pairingSession=await api('/api/onboarding/pair-admin/session',{method:'POST',body:'{}'});document.querySelector('#pairCode').textContent=`Code ${pairingSession.code} · gültig bis ${new Date(pairingSession.expiresAt).toLocaleTimeString()}`;document.querySelector('#pairQr').src=pairingSession.qrDataUrl;document.querySelector('#pairingPanel').hidden=false;toast('Lokaler QR-Code für das Admin-Pairing erstellt.')}catch(e){toast(e.message)}})
document.querySelector('#simulateQrScan').addEventListener('click',async()=>{if(!pairingSession)return toast('Zuerst Pairing starten');try{await api('/api/onboarding/pair-admin/complete',{method:'POST',body:JSON.stringify({token:pairingSession.token,code:pairingSession.code})});pairingSession=null;document.querySelector('#pairingPanel').hidden=true;await refresh(false);toast('QR-Scan und Admin-Pairing lokal simuliert')}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}})
document.querySelector('#pairHue').addEventListener('click',async()=>{try{if(!latestState.integrations.hue.discovered)await api('/api/integrations/hue/discover');await api('/api/integrations/hue/pair',{method:'POST',body:'{}'});await refresh(true);toast(latestState?.integrations?.hue?.mode==='simulation'?'Hue-Simulation gekoppelt':'Hue gekoppelt')}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}})
