document.querySelector('#addRoom').addEventListener('click',async()=>{const i=document.querySelector('#newRoomName'),name=i.value.trim();if(!name)return toast('Raumname fehlt');await api('/api/rooms',{method:'POST',body:JSON.stringify({name})});i.value='';await refresh(false);await populateRooms()})
document.querySelector('#addSimDevice').addEventListener('click',async()=>{const type=document.querySelector('#deviceType').value,roomId=document.querySelector('#deviceRoom').value,name=document.querySelector('#deviceName').value.trim();try{await api('/api/devices/simulate',{method:'POST',body:JSON.stringify({type,roomId,name})});document.querySelector('#deviceName').value='';await refresh(false);toast('Simulationsgerät angelegt')}catch(e){toast(e.message)}})
document.querySelector('#openDeviceWizard').addEventListener('click',async()=>{try{wizardIntegrations=await api('/api/device-onboarding/integrations');wizardStep=0;wizardCandidates=[];wizardData={integration:'simulation',candidateId:'',profile:'light',roomId:'',name:'',experimentalAccepted:false};document.querySelector('#wizardBack').hidden=false;renderWizard();document.querySelector('#deviceWizard').showModal()}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}})
document.querySelector('#mobileAddDevice').addEventListener('click',()=>document.querySelector('#openDeviceWizard').click())
document.querySelector('#closeDeviceWizard').addEventListener('click',()=>document.querySelector('#deviceWizard').close())
document.querySelector('#wizardBack').addEventListener('click',()=>{if(wizardStep>0){if(wizardStep===2){try{captureWizard()}catch{}}wizardStep--;renderWizard()}})
document.querySelector('#wizardNext').addEventListener('click',async()=>{try{if(wizardStep===4){document.querySelector('#deviceWizard').close();document.querySelector('#wizardBack').hidden=false;return}captureWizard();if(wizardStep===0){wizardCandidates=[];wizardData.candidateId='';wizardData.name='';wizardStep=1;renderWizard();await discoverWizardDevices();return}if(wizardStep<3){wizardStep++;renderWizard();return}const result=await api('/api/device-onboarding/complete',{method:'POST',body:JSON.stringify(wizardData)});wizardStep=4;const checks=Object.fromEntries((result.test.checks||[]).map(check=>[check.id,check.ok]));document.querySelector('#wizardContent').innerHTML=`<div class="wizard-success"><span>✓</span><h3>${esc(result.device.name)} ist bereit</h3><p class="muted">${esc(result.test.message)} · ${Number(result.test.latencyMs)||0} ms</p><ul class="wizard-test-report"><li>${checks.identity?'✓':'–'} Identität</li><li>${checks.availability?'✓':'–'} Erreichbarkeit</li><li>${checks.capabilities?'✓':'–'} Funktionen</li></ul></div>`;document.querySelector('#wizardBack').hidden=true;document.querySelector('#wizardNext').textContent='Fertig';await refresh(false);toast('Gerät erfolgreich hinzugefügt')}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}})
document.querySelector('#automationTemplate').insertAdjacentHTML('beforeend','<option value="sun-device">Gerät bei Sonnenauf- oder -untergang</option>');document.querySelector('#automationTime').insertAdjacentHTML('afterend','<div id="solarFields" class="solar-fields" hidden><select id="automationSolarEvent" aria-label="Sonnenereignis"><option value="sunrise">Sonnenaufgang</option><option value="sunset">Sonnenuntergang</option></select><label>Offset in Minuten<input id="automationSolarOffset" type="number" min="-720" max="720" step="1" value="0" aria-label="Sonnenoffset in Minuten"></label><p class="muted">Wird täglich aus den lokal gespeicherten Koordinaten berechnet – ohne Cloud. Ohne Standort bleibt die Automation sicher inaktiv.</p></div><select id="automationAction2" aria-label="Zweites Aktionsgerät"><option value="">Keine zweite Aktion</option></select><details class="automation-condition"><summary>Optionale Bedingung</summary><select id="automationConditionDevice" aria-label="Bedingungsgerät"><option value="">Keine Bedingung</option></select><select id="automationConditionCapability" aria-label="Bedingungsfeld"></select><select id="automationConditionOperator" aria-label="Bedingungsoperator"></select><input id="automationConditionValue" aria-label="Bedingungswert" placeholder="Wert"></details>');
function updateAutomationTemplateFields(){const template=document.querySelector('#automationTemplate').value,isSun=template==='sun-device',isTime=template==='time-device';document.querySelector('#solarFields').hidden=!isSun;document.querySelector('#automationTime').hidden=!isTime;document.querySelector('#automationTrigger').hidden=isSun||isTime;document.querySelector('#automationThreshold').hidden=isSun||isTime}document.querySelector('#automationTemplate').addEventListener('change',updateAutomationTemplateFields);updateAutomationTemplateFields();
async function updateConditionFields(){const deviceId=document.querySelector('#automationConditionDevice').value,device=latestState?.devices?.find(item=>item.id===deviceId),field=document.querySelector('#automationConditionCapability'),operator=document.querySelector('#automationConditionOperator');field.innerHTML=device?Object.entries(device.capabilities).filter(([,value])=>['number','string','boolean'].includes(typeof value)).map(([key,value])=>`<option value="${esc(key)}" data-type="${typeof value}">${esc(key)}</option>`).join(''):'';const value=device?.capabilities?.[field.value];operator.innerHTML=(typeof value==='number'?['above','below','equals','notEquals']:['equals','notEquals']).map(id=>`<option value="${id}">${{above:'größer als',below:'kleiner als',equals:'ist gleich',notEquals:'ist nicht gleich'}[id]}</option>`).join('')}
document.querySelector('#automationConditionDevice').addEventListener('change',updateConditionFields);document.querySelector('#automationConditionCapability').addEventListener('change',updateConditionFields);
document.querySelector('#addAutomation').addEventListener('click',async()=>{const conditionDeviceId=document.querySelector('#automationConditionDevice').value,fieldOption=document.querySelector('#automationConditionCapability').selectedOptions[0],rawValue=document.querySelector('#automationConditionValue').value,conditionValue=fieldOption?.dataset.type==='number'?Number(rawValue):fieldOption?.dataset.type==='boolean'?rawValue==='true':rawValue,offsetMinutes=Number(document.querySelector('#automationSolarOffset').value);if(!Number.isInteger(offsetMinutes)||Math.abs(offsetMinutes)>720)return toast('Sonnenoffset muss eine ganze Minute zwischen -720 und 720 sein.');const body={templateId:document.querySelector('#automationTemplate').value,triggerDeviceId:document.querySelector('#automationTrigger').value,actionDeviceId:document.querySelector('#automationAction').value,secondActionDeviceId:document.querySelector('#automationAction2').value,threshold:Number(document.querySelector('#automationThreshold').value),at:document.querySelector('#automationTime').value,event:document.querySelector('#automationSolarEvent').value,offsetMinutes,conditionDeviceId,conditionCapability:document.querySelector('#automationConditionCapability').value,conditionOperator:document.querySelector('#automationConditionOperator').value,conditionValue};try{await api('/api/automations/from-template',{method:'POST',body:JSON.stringify(body)});await refresh(false);toast(body.templateId==='sun-device'?(latestState.home?.location?'Sonnenautomation lokal berechnet und angelegt':'Sonnenautomation angelegt; bis zum lokalen Standort sicher inaktiv'):'Lokale Automation mit geprüfter Aktionskette angelegt')}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}})
document.querySelector('#saveHome').addEventListener('click',async()=>{const latitude=Number(document.querySelector('#homeLatitude').value),longitude=Number(document.querySelector('#homeLongitude').value),name=document.querySelector('#homeName').value.trim();try{await api('/api/home',{method:'PATCH',body:JSON.stringify({name,location:{latitude,longitude}})});await refresh(false);toast('Haus und Koordinaten lokal gespeichert')}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}})
document.querySelector('#themeSelect').addEventListener('change',async event=>{const previous=document.body.dataset.theme;applyTheme(event.target.value);try{await api('/api/settings/theme',{method:'PATCH',body:JSON.stringify({theme:event.target.value})});toast(`${event.target.value} ist jetzt aktiv`)}catch(e){applyTheme(previous);toast(`${e.code||'FEHLER'}: ${e.message}`)}})
document.querySelector('#mobileThemeSelect').addEventListener('change',event=>{document.querySelector('#themeSelect').value=event.target.value;document.querySelector('#themeSelect').dispatchEvent(new Event('change'))})
document.querySelectorAll('[data-more-open]').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.moreOpen)))
document.querySelector('#localeSelect').addEventListener('change',async event=>{try{await api('/api/settings/locale',{method:'PATCH',body:JSON.stringify({locale:event.target.value})});const bundle=await api(`/api/i18n/messages?locale=${encodeURIComponent(event.target.value)}`);document.documentElement.lang=bundle.locale;toast(event.target.value==='de'?'Sprache gespeichert':'Language saved · Beta')}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}})
document.querySelector('#firstRunNext').addEventListener('click',()=>advanceFirstRun(false).catch(e=>toast(`${e.code||'FEHLER'}: ${e.message}`)))
document.querySelector('#firstRunSkip').addEventListener('click',()=>advanceFirstRun(true).catch(e=>toast(`${e.code||'FEHLER'}: ${e.message}`)))
const themeChoiceObserver=new MutationObserver(()=>{for(const card of document.querySelectorAll('.theme-preview.disabled')){const id=card.querySelector('strong')?.textContent;if(!['Compact','Living'].includes(id))continue;card.classList.remove('disabled');const input=card.querySelector('input');input.disabled=false;input.name='firstTheme';input.value=id;card.querySelector('small').textContent=id==='Compact'?'Mehr Überblick':'Weich und wohnlich';input.addEventListener('change',event=>{previewTheme=event.target.value;applyTheme(previewTheme)},{once:true})}});themeChoiceObserver.observe(document.querySelector('#firstRunContent'),{childList:true,subtree:true})
document.querySelector('#downloadBackup').addEventListener('click',async()=>{try{const backup=await api('/api/backup'),blob=new Blob([JSON.stringify(backup,null,2)+'\n'],{type:'application/json'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`systemone-backup-${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Lokales Backup erstellt')}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}})
document.querySelector('#backupFile').addEventListener('change',async event=>{validatedBackup=null;document.querySelector('#restoreBackup').disabled=true;const file=event.target.files?.[0];if(!file)return;try{if(file.size>1024*1024)throw new Error('Backup-Datei ist größer als 1 MB.');const backup=JSON.parse(await file.text()),summary=await api('/api/backup/validate',{method:'POST',body:JSON.stringify(backup)});validatedBackup=backup;document.querySelector('#backupSummary').innerHTML=`<strong>Backup ist gültig</strong><div class="backup-facts"><span>Schema v${esc(summary.schemaVersion)}</span><span>${esc(summary.rooms)} Räume</span><span>${esc(summary.devices)} Geräte</span><span>${new Date(summary.createdAt).toLocaleString()}</span></div><code>SHA-256 ${esc(summary.checksum)}</code>`;document.querySelector('#restoreBackup').disabled=false;toast('Backup erfolgreich geprüft')}catch(e){document.querySelector('#backupSummary').innerHTML=`<strong class="backup-error">Backup wurde abgewiesen</strong><p class="muted">${esc(e.message)}</p>`;toast(`${e.code||'BACKUP_INVALID'}: ${e.message}`)}})
document.querySelector('#restoreBackup').addEventListener('click',async()=>{if(!validatedBackup)return;const button=document.querySelector('#restoreBackup');if(button.dataset.confirm!=='yes'){button.dataset.confirm='yes';button.textContent='Restore jetzt bestätigen';toast('Nochmal klicken, um das geprüfte Backup wiederherzustellen');return}try{const result=await api('/api/backup/restore',{method:'POST',body:JSON.stringify(validatedBackup)});validatedBackup=null;button.disabled=true;button.dataset.confirm='';button.textContent='Geprüftes Backup wiederherstellen';document.querySelector('#backupFile').value='';await refresh(false);document.querySelector('#backupSummary').innerHTML=`<strong>Restore abgeschlossen</strong><p class="muted">${esc(result.rooms)} Räume und ${esc(result.devices)} Simulationsgeräte wiederhergestellt.</p>`;toast('Backup lokal wiederhergestellt')}catch(e){button.dataset.confirm='';button.textContent='Geprüftes Backup wiederherstellen';toast(`${e.code||'FEHLER'}: ${e.message}`)}})
document.querySelector('#refresh').addEventListener('click',()=>refresh(true).catch(e=>toast(e.message)));document.querySelector('#diagnose').addEventListener('click',()=>renderDiagnostics().then(()=>toast('Diagnose aktualisiert')));
const restartSetupButton=document.createElement('button');restartSetupButton.innerHTML='<span class="more-icon">↻</span><span><strong>Einrichtung erneut öffnen</strong><small>Fortschritt zurücksetzen, lokale Daten behalten</small></span><b>›</b>';document.querySelector('.more-menu')?.append(restartSetupButton);restartSetupButton.addEventListener('click',async()=>{try{firstRunFlow=await api('/api/onboarding/reset',{method:'POST',body:'{}'});renderFirstRun();document.querySelector('#firstRun').showModal();toast('Einrichtung wurde neu geöffnet')}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}})
const startDisplayButton=document.createElement('button');startDisplayButton.innerHTML='<span class="more-icon">▣</span><span><strong>Wanddisplay starten</strong><small>Sichere Nur-Anzeige-Session auf diesem Bildschirm</small></span><b>›</b>';document.querySelector('.more-menu')?.append(startDisplayButton);startDisplayButton.addEventListener('click',async()=>{try{const result=await api('/api/admin/display-sessions',{method:'POST',body:'{}'});location.href=result.launchUrl}catch(e){toast(`${e.code||'FEHLER'}: ${e.message}`)}})
async function populateRooms(){const rooms=await api('/api/rooms');document.querySelector('#deviceRoom').innerHTML='<option value="">Ohne Raum</option>'+rooms.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('')}
function renderLoadingState(){document.querySelector('#overviewStats').innerHTML=Array.from({length:4},()=>'<div class="stat-card skeleton" aria-hidden="true"><span></span><span></span></div>').join('');roomsEl.innerHTML='<div class="room-card skeleton" aria-hidden="true"><span></span><span></span><span></span></div>'}
for(const [selector,label] of Object.entries({'#newRoomName':'Name des neuen Raums','#deviceType':'Gerätetyp','#deviceRoom':'Raum für Simulationsgerät','#deviceName':'Name des Simulationsgeräts','#homeName':'Name des Zuhauses','#homeLatitude':'Breitengrad','#homeLongitude':'Längengrad','#automationTemplate':'Automationsvorlage','#automationTrigger':'Auslösendes Gerät','#automationAction':'Aktionsgerät'}))document.querySelector(selector)?.setAttribute('aria-label',label);
renderLoadingState();showView(viewCopy[location.hash.slice(1)]?location.hash.slice(1):'overview');refresh(false).then(populateRooms).then(openFirstRun).then(startDeviceEvents).catch(e=>toast(e.message));window.addEventListener('beforeunload',()=>{clearInterval(liveTimer);clearTimeout(liveRefreshTimer);liveSource?.close();themeChoiceObserver.disconnect()});
